/**
 * Argument parsing per the README.
 *
 * parseArgs(argv) returns `{ retries: int }`:
 *   - `--retry <n>` sets the retry count (default 0).
 *   - `--retry` without a value is an error.
 *   - Non-numeric or negative retry counts are errors.
 */
export function parseArgs(argv) {
  let retries = 0
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] !== '--retry') continue

    const raw = argv[i + 1]
    if (raw === undefined) {
      throw new Error('--retry requires a value, e.g. --retry 3')
    }

    const value = Number(raw)
    if (!Number.isInteger(value) || value < 0) {
      throw new Error(`invalid retry count: ${raw}`)
    }

    retries = value
    i += 1
  }
  return { retries }
}

/**
 * Retry logic per the README.
 *
 * retryWithBackoff(fn, retries) calls `fn()` and, on a thrown transient error
 * (`code === 'ETIMEDOUT'` or `'ECONNRESET'`), retries up to `retries` times
 * with a short exponential backoff delay. Any other error propagates
 * immediately.
 */

const TRANSIENT_CODES = new Set(['ETIMEDOUT', 'ECONNRESET'])

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

// Short backoff: 1ms, 2ms, 4ms, ... capped at 32ms.
function delayFor(attempt) {
  return Math.min(2 ** attempt, 32)
}

function isTransient(error) {
  return (
    error !== null &&
    typeof error === 'object' &&
    TRANSIENT_CODES.has(error.code)
  )
}

export async function retryWithBackoff(fn, retries) {
  const maxRetries = Math.max(0, Number(retries) || 0)
  for (let attempt = 0; ; attempt++) {
    try {
      return await fn()
    } catch (error) {
      if (!isTransient(error) || attempt >= maxRetries) throw error
      await sleep(delayFor(attempt))
    }
  }
}

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { parseArgs } from '../src/args.js'

test('args: default retries is 0', () => {
  assert.deepEqual(parseArgs(['run']), { retries: 0 })
})

test('args: --retry <n> sets the count', () => {
  assert.deepEqual(parseArgs(['run', '--retry', '3']), { retries: 3 })
})

test('args: --retry 0 is allowed', () => {
  assert.deepEqual(parseArgs(['run', '--retry', '0']), { retries: 0 })
})

test('args: --retry without value is an error', () => {
  assert.throws(() => parseArgs(['run', '--retry']))
})

test('args: --retry at the very end of argv is an error', () => {
  assert.throws(() => parseArgs(['--retry']))
})

test('args: --retry with a non-numeric value is an error', () => {
  assert.throws(() => parseArgs(['run', '--retry', 'abc']))
  assert.throws(() => parseArgs(['run', '--retry', '3.5']))
  assert.throws(() => parseArgs(['run', '--retry', '--verbose']))
})

test('args: --retry with a negative value is an error', () => {
  assert.throws(() => parseArgs(['run', '--retry', '-1']))
})

test('args: the last --retry wins', () => {
  assert.deepEqual(parseArgs(['run', '--retry', '1', '--retry', '5']), {
    retries: 5,
  })
})

test('args: unrelated arguments are ignored', () => {
  assert.deepEqual(
    parseArgs(['run', '--verbose', '--retry', '2', 'target']),
    { retries: 2 }
  )
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { retryWithBackoff } from '../src/retry.js'

const transient = (message, code = 'ETIMEDOUT') => {
  const error = new Error(message)
  error.code = code
  return error
}

test('retry: succeeds on the first call', async () => {
  const result = await retryWithBackoff(() => Promise.resolve('ok'), 3)
  assert.equal(result, 'ok')
})

test('retry: retries a transient failure then succeeds', async () => {
  let calls = 0
  const result = await retryWithBackoff(() => {
    calls += 1
    if (calls === 1) return Promise.reject(transient('timeout'))
    return Promise.resolve('ok')
  }, 3)
  assert.equal(result, 'ok')
  assert.equal(calls, 2)
})

test('retry: retries ECONNRESET as transient', async () => {
  let calls = 0
  const result = await retryWithBackoff(() => {
    calls += 1
    if (calls === 1) return Promise.reject(transient('reset', 'ECONNRESET'))
    return Promise.resolve('ok')
  }, 2)
  assert.equal(result, 'ok')
  assert.equal(calls, 2)
})

test('retry: handles synchronous throws', async () => {
  let calls = 0
  const result = await retryWithBackoff(() => {
    calls += 1
    if (calls === 1) throw transient('timeout')
    return 'ok'
  }, 2)
  assert.equal(result, 'ok')
  assert.equal(calls, 2)
})

test('retry: gives up after retries are exhausted', async () => {
  await assert.rejects(() =>
    retryWithBackoff(() => Promise.reject(transient('timeout')), 2)
  )
})

test('retry: calls fn retries+1 times before giving up', async () => {
  let calls = 0
  await assert.rejects(() =>
    retryWithBackoff(() => {
      calls += 1
      return Promise.reject(transient('timeout'))
    }, 2)
  )
  assert.equal(calls, 3)
})

test('retry: propagates the last error after exhaustion', async () => {
  await assert.rejects(
    () => retryWithBackoff(() => Promise.reject(transient('timeout')), 1),
    (error) => error.code === 'ETIMEDOUT'
  )
})

test('retry: retries=0 propagates the transient error immediately', async () => {
  let calls = 0
  await assert.rejects(() =>
    retryWithBackoff(() => {
      calls += 1
      return Promise.reject(transient('timeout'))
    }, 0)
  )
  assert.equal(calls, 1)
})

test('retry: does not retry non-transient errors', async () => {
  let calls = 0
  await assert.rejects(
    () =>
      retryWithBackoff(() => {
        calls += 1
        return Promise.reject(new Error('boom'))
      }, 3),
    /boom/
  )
  assert.equal(calls, 1)
})

test('retry: stops at the first non-transient error', async () => {
  let calls = 0
  await assert.rejects(() =>
    retryWithBackoff(() => {
      calls += 1
      if (calls === 1) return Promise.reject(transient('timeout'))
      return Promise.reject(new Error('boom'))
    }, 3)
  )
  assert.equal(calls, 2)
})

test('retry: undefined retries behaves like 0', async () => {
  let calls = 0
  await assert.rejects(() =>
    retryWithBackoff(() => {
      calls += 1
      return Promise.reject(transient('timeout'))
    })
  )
  assert.equal(calls, 1)
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { retryWithBackoff } from '../src/retry.js'

/**
 * Acceptance criterion from the README: with 30% packet-loss network
 * conditions, the success rate over a run must be >= 99%.
 *
 * Each attempt fails independently with probability LOSS_RATE (an
 * ETIMEDOUT, which retryWithBackoff treats as transient). With retries=4
 * a run only fails if all 5 attempts are lost: 0.3^5 = 0.243%, so the
 * expected success rate is ~99.76%. Over 1000 runs the binomial tail
 * beyond 10 failures is astronomically small; the seed makes the outcome
 * fully deterministic.
 */

const RUNS = 1000
const LOSS_RATE = 0.3
const RETRIES = 4

// Deterministic PRNG so the statistical test is reproducible.
function mulberry32(seed) {
  let a = seed >>> 0
  return function () {
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function flakyNetwork(random) {
  return () => {
    if (random() < LOSS_RATE) {
      const error = new Error('socket timed out')
      error.code = 'ETIMEDOUT'
      return Promise.reject(error)
    }
    return Promise.resolve('ok')
  }
}

async function countFailures(random, retries) {
  let failures = 0
  for (let i = 0; i < RUNS; i++) {
    try {
      await retryWithBackoff(flakyNetwork(random), retries)
    } catch {
      failures += 1
    }
  }
  return failures
}

test('acceptance: >=99% success rate under 30% packet loss with retries', async () => {
  const failures = await countFailures(mulberry32(42), RETRIES)
  const successRate = (RUNS - failures) / RUNS
  assert.ok(
    successRate >= 0.99,
    `success rate ${successRate} (${failures}/${RUNS} failed) is below 0.99`
  )
})

test('acceptance: without retries the same network fails far more often', async () => {
  const failures = await countFailures(mulberry32(42), 0)
  const successRate = (RUNS - failures) / RUNS
  assert.ok(
    failures > 100,
    `expected many failures under 30% loss without retries, got ${failures} (success rate ${successRate})`
  )
})

import { test } from 'node:test'
import assert from 'node:assert/strict'
import { main } from '../src/cli.js'

test('cli: prints the result', async () => {
  const logs = []
  const original = console.log
  console.log = (message) => logs.push(message)
  try {
    await main(['run'])
  } finally {
    console.log = original
  }
  assert.deepEqual(logs, ['ok'])
})

test('cli: --retry without a value rejects', async () => {
  await assert.rejects(() => main(['run', '--retry']))
})
